const existing = (await listEncountersForCampaign(campaign.Id)).find((e) => e.Id === req.params.encounterId);
if (!existing) { res.status(404).json({ error: 'No such Encounter.' }); return; }

// Clear every Hero's Strain — V0.6 ruleset: all Strain is cleared when Combat ends.
for (const participant of existing.Participants) {
  if (participant.Kind !== 'PC') continue;
  const sheet = await getSheet(participant.RefId);
  if (!sheet) continue;
  if (!sheet.Strain.some((s) => s)) continue;
  sheet.Strain = sheet.Strain.map(() => false);
  await saveSheet(sheet, campaign.Id);
}

