  it('refuses to end an Encounter on an archived campaign', async () => {
    vi.mocked(repo.getCampaign).mockResolvedValue(makeCampaign({ Status: 'Archived' }));
    vi.mocked(repo.membershipFor).mockResolvedValue(gmMembership);
    vi.mocked(repo.listEncountersForCampaign).mockResolvedValue([makeEncounter()]);

    const res = await request(appAs('u-mike')).post('/campaigns/cm-1/combat/enc-1/end');

    expect(res.status).toBe(409);
    expect(repo.saveEncounter).not.toHaveBeenCalled();
  });

  it('clears Strain on all PC Heroes and adds a history entry', async () => {
    vi.mocked(repo.getCampaign).mockResolvedValue(makeCampaign());
    vi.mocked(repo.membershipFor).mockResolvedValue(gmMembership);
    const participants: Participant[] = [
      { Kind: 'PC', RefId: 'ch-1' },
      { Kind: 'PC', RefId: 'ch-2' },
      { Kind: 'Enemy' },
    ];
    vi.mocked(repo.listEncountersForCampaign).mockResolvedValue([
      makeEncounter({ Participants: participants, History: [{ Id: 'ch-old', At: '2026-01-01T01:00:00Z', Text: 'Some event' }] }),
    ]);
    vi.mocked(repo.getSheet).mockImplementation(async (charId) => {
      if (charId === 'ch-1') return { Id: 's-1', CharacterId: 'ch-1', Strain: [true, false, true, false, false] } as CharacterSheet;
      return { Id: 's-2', CharacterId: 'ch-2', Strain: [false, false, false, false, false] } as CharacterSheet;
    });
    const mockNow = '2026-01-01T02:00:00Z';
    vi.mocked(repo.nowIso).mockReturnValue(mockNow);

    const res = await request(appAs('u-mike')).post('/campaigns/cm-1/combat/enc-1/end');

    expect(res.status).toBe(200);
    expect(res.body.encounter.Status).toBe('Ended');
    // ch-1 sheet was saved with Strain cleared
    expect(repo.saveSheet).toHaveBeenCalledTimes(1);
    expect(repo.saveSheet).toHaveBeenCalledWith(
      expect.objectContaining({ CharacterId: 'ch-1', Strain: [false, false, false, false, false] }),
      'cm-1'
    );
    // ch-2 sheet was NOT saved (no Strain marked)
    expect(repo.saveSheet).not.toHaveBeenCalledWith(
      expect.objectContaining({ CharacterId: 'ch-2' }),
      expect.anything()
    );
    // Enemy participant did not trigger a sheet read — getSheet was only called for PC participants
    expect(repo.getSheet).toHaveBeenCalledWith('ch-1');
    expect(repo.getSheet).toHaveBeenCalledWith('ch-2');
    expect(repo.getSheet).not.toHaveBeenCalledWith(expect.anything(), 'Enemy');
    // History entry was prepended
    expect(res.body.encounter.History).toHaveLength(2);
    expect(res.body.encounter.History[0].Text).toBe('Combat ended.');
    expect(res.body.encounter.History[0].At).toBe(mockNow);
  });

  it('refuses a non-GM and reads/writes no sheets', async () => {
    vi.mocked(repo.getCampaign).mockResolvedValue(makeCampaign());
    const nonGmMembership: Membership = { Id: 'mb-player', UserId: 'u-ryan', CampaignId: 'cm-1', Role: 'Player', CharacterId: 'ch-1' };
    vi.mocked(repo.membershipFor).mockResolvedValue(nonGmMembership);
    vi.mocked(repo.listEncountersForCampaign).mockResolvedValue([
      makeEncounter({ Participants: [{ Kind: 'PC', RefId: 'ch-1' }] as Participant[] }),
    ]);

    const res = await request(appAs('u-ryan')).post('/campaigns/cm-1/combat/enc-1/end');

    expect(res.status).toBe(403);
    expect(repo.saveEncounter).not.toHaveBeenCalled();
    expect(repo.getSheet).not.toHaveBeenCalled();
    expect(repo.saveSheet).not.toHaveBeenCalled();
  });

  it('skips null sheets without crashing', async () => {
    vi.mocked(repo.getCampaign).mockResolvedValue(makeCampaign());
    vi.mocked(repo.membershipFor).mockResolvedValue(gmMembership);
    vi.mocked(repo.listEncountersForCampaign).mockResolvedValue([
      makeEncounter({ Participants: [{ Kind: 'PC', RefId: 'ch-none' }] } as unknown as Encounter),
    ]);
    vi.mocked(repo.getSheet).mockResolvedValue(null);

    const res = await request(appAs('u-mike')).post('/campaigns/cm-1/combat/enc-1/end');

    expect(res.status).toBe(200);
    expect(res.body.encounter.Status).toBe('Ended');
    expect(repo.saveSheet).not.toHaveBeenCalled();
  });
});

